<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import maplibregl from 'maplibre-gl'
import { Globe2, Layers3, MapPinned, ChartNoAxesCombined, Search, Bell, ChevronDown, ChevronRight, Plus, Minus, Compass, Maximize, LocateFixed, Ruler, Download, X, Check, SlidersHorizontal, ArrowUpRight, Activity, Navigation, CircleHelp, PanelLeftClose, MousePointer2, RotateCcw, Map, Sun, Crosshair } from 'lucide-vue-next'
import { sites, boundary, routes, districts, distance } from './data'
const mapEl=ref<HTMLElement>(); let map:maplibregl.Map|undefined
const activeTab=ref('空间探索'), query=ref(''), district=ref('全部区域'), mode=ref('散点分布'), basemap=ref('浅色地图')
const layers=ref([{id:'sites',name:'城市感知节点',sub:'180 个点要素',color:'#5977eb',visible:true},{id:'routes',name:'核心交通走廊',sub:'2 条线要素',color:'#15aa96',visible:true},{id:'boundary',name:'研究区域边界',sub:'上海中心城区',color:'#e3a748',visible:true}])
const selected=ref<Record<string,any>|null>(null), toast=ref(''), measuring=ref(false), measurePoints=ref<number[][]>([]), mapError=ref(false), ready=ref(false), zoom=ref(11.4), coordinates=ref('121.4900° E · 31.2350° N'), panelOpen=ref(true), time=ref(14), timelinePlaying=ref(false), notice=ref(false)
let toastTimer:ReturnType<typeof setTimeout>; let playTimer:ReturnType<typeof setInterval>|undefined
const filtered=computed(()=>sites.features.filter(f=>(district.value==='全部区域'||f.properties?.district===district.value)&&(!query.value||String(f.properties?.name).includes(query.value)||String(f.properties?.district).includes(query.value))))
const average=computed(()=>Math.round(filtered.value.reduce((s,f)=>s+Number(f.properties?.value),0)/(filtered.value.length||1)))
const attention=computed(()=>filtered.value.filter(f=>f.properties?.status==='需关注').length)
const measureLength=computed(()=>measurePoints.value.slice(1).reduce((s,p,i)=>s+distance(measurePoints.value[i],p),0).toFixed(2))
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3500)}
function updateData(){if(!ready.value)return; (map?.getSource('sites') as maplibregl.GeoJSONSource)?.setData({type:'FeatureCollection',features:filtered.value}); applyLayers()}
function applyLayers(){if(!ready.value||!map)return;for(const l of layers.value){for(const id of l.id==='sites'?['site-circles','site-heat']:l.id==='boundary'?['boundary-fill','boundary-line']:['route-lines']) map.setLayoutProperty(id,'visibility',l.visible&&(id!=='site-circles'||mode.value==='散点分布')&&(id!=='site-heat'||mode.value==='热力密度')?'visible':'none')} }
function focusSite(id:number){const f=sites.features.find(f=>f.properties?.id===id);if(f){selected.value=f.properties; map?.flyTo({center:f.geometry.coordinates as [number,number],zoom:14,duration:1000})}}
function reset(){map?.flyTo({center:[121.49,31.235],zoom:11.4,pitch:0,bearing:0});selected.value=null;district.value='全部区域';query.value=''}
function exportData(){const blob=new Blob([JSON.stringify({type:'FeatureCollection',features:filtered.value},null,2)],{type:'application/geo+json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='atlas-shanghai-nodes.geojson';a.click();URL.revokeObjectURL(url);notify(`已导出 ${filtered.value.length} 个要素`)}
function toggleMeasure(){measuring.value=!measuring.value;measurePoints.value=[];updateMeasure();notify(measuring.value?'点击地图添加测距点，再次点击工具结束':'测距已结束')}
function updateMeasure(){(map?.getSource('measure') as maplibregl.GeoJSONSource)?.setData({type:'FeatureCollection',features:measurePoints.value.length>1?[{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:measurePoints.value}}]:[]})}
function togglePlay(){timelinePlaying.value=!timelinePlaying.value;if(playTimer)clearInterval(playTimer);if(timelinePlaying.value)playTimer=setInterval(()=>time.value=(time.value+1)%24,900)}
watch([query,district,mode],updateData);watch(layers,applyLayers,{deep:true})
watch(basemap,()=>{if(!map||!ready.value)return;map.setPaintProperty('base-raster','raster-saturation',basemap.value==='浅色地图'?-0.85:0);map.setPaintProperty('base-raster','raster-brightness-max',basemap.value==='夜间地图'?.35:1);map.setPaintProperty('background','background-color',basemap.value==='夜间地图'?'#1b293e':'#eaf0f3')})
watch(time,()=>{if(ready.value)map?.setPaintProperty('site-heat','heatmap-intensity',.6+time.value/24)})
onMounted(()=>{if(window.innerWidth<=560)panelOpen.value=false;try{map=new maplibregl.Map({container:mapEl.value!,center:[121.49,31.235],zoom:11.4,attributionControl:false,style:{version:8,sources:{'base':{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'background',type:'background',paint:{'background-color':'#eaf0f3'}},{id:'base-raster',type:'raster',source:'base',paint:{'raster-saturation':-.85,'raster-opacity':.65}}]}});map.addControl(new maplibregl.AttributionControl({compact:true}));map.addControl(new maplibregl.ScaleControl({unit:'metric'}),'bottom-left');map.on('error',()=>mapError.value=true);map.on('load',()=>{if(!map)return;map.addSource('boundary',{type:'geojson',data:boundary});map.addLayer({id:'boundary-fill',type:'fill',source:'boundary',paint:{'fill-color':'#7189ee','fill-opacity':.07}});map.addLayer({id:'boundary-line',type:'line',source:'boundary',paint:{'line-color':'#8596d9','line-width':2,'line-dasharray':[3,3]}});map.addSource('routes',{type:'geojson',data:routes});map.addLayer({id:'route-lines',type:'line',source:'routes',paint:{'line-color':'#22afad','line-width':3,'line-opacity':.7}});map.addSource('sites',{type:'geojson',data:sites});map.addLayer({id:'site-heat',type:'heatmap',source:'sites',layout:{visibility:'none'},paint:{'heatmap-weight':['interpolate',['linear'],['get','value'],0,0,100,1],'heatmap-radius':35,'heatmap-opacity':.75,'heatmap-color':['interpolate',['linear'],['heatmap-density'],0,'rgba(81,111,240,0)',.2,'#8bd3eb',.5,'#6089e9',.8,'#eab86c',1,'#ef6e65']}});map.addLayer({id:'site-circles',type:'circle',source:'sites',paint:{'circle-radius':['interpolate',['linear'],['zoom'],10,4,15,9],'circle-color':['match',['get','category'],0,'#5d7ce9',1,'#22b5a1',2,'#efa94e','#a377d9'],'circle-stroke-color':'#ffffff','circle-stroke-width':1.5,'circle-opacity':.9}});map.addSource('measure',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'measure-line',type:'line',source:'measure',paint:{'line-color':'#ef6e65','line-width':3,'line-dasharray':[2,2]}});ready.value=true;updateData();map.on('click','site-circles',e=>{if(!measuring.value&&e.features?.[0])selected.value=e.features[0].properties});map.on('mouseenter','site-circles',()=>map!.getCanvas().style.cursor='pointer');map.on('mouseleave','site-circles',()=>map!.getCanvas().style.cursor='');});map.on('mousemove',e=>coordinates.value=`${e.lngLat.lng.toFixed(4)}° E · ${e.lngLat.lat.toFixed(4)}° N`);map.on('zoom',()=>zoom.value=map!.getZoom());map.on('click',e=>{if(measuring.value){measurePoints.value.push([e.lngLat.lng,e.lngLat.lat]);updateMeasure()}})}catch{mapError.value=true;notify('WebGL 地图初始化失败，请使用支持 WebGL 的浏览器')}})
onBeforeUnmount(()=>{map?.remove();clearTimeout(toastTimer);if(playTimer)clearInterval(playTimer)})
</script>

<template>
<div class="app-shell">
  <aside class="rail"><a class="brand-mark" title="ATLAS" @click="reset"><Globe2 :size="27"/></a><div class="rail-nav"><button v-for="(item,i) in [{name:'空间探索',icon:MapPinned},{name:'数据目录',icon:Layers3},{name:'空间分析',icon:ChartNoAxesCombined}]" :key="i" :class="{active:activeTab===item.name}" :title="item.name" @click="activeTab=item.name"><component :is="item.icon" :size="22"/></button></div><div class="rail-bottom"><button title="使用帮助" @click="notify('点击节点查看属性；使用图层面板切换可视化，测距工具支持多点距离。')"><CircleHelp :size="21"/></button><div class="avatar">CY</div></div></aside>
  <div class="main-shell">
    <header class="topbar"><div class="wordmark">ATLAS<span>空间智能工作台</span></div><div class="breadcrumb">工作空间 <ChevronRight :size="14"/><strong>上海城市数字底座</strong><span class="project-tag">DEMO</span></div><div class="header-right"><span class="live"><i/>系统在线</span><button class="icon-button" @click="notice=!notice" title="通知"><Bell :size="19"/><b class="notification-dot"/></button><div class="header-divider"/><span class="username">城市研究员</span><div class="avatar small">CY</div></div></header>
    <div class="workspace-heading"><div><div class="eyebrow">URBAN SPATIAL EXPLORER</div><h1>城市空间探索 <span>上海 · 中心城区</span></h1><p>连接城市数据，发现空间价值。</p></div><div class="heading-actions"><span class="demo-label"><i/>模拟数据 · 180 个节点</span><button class="button" @click="reset"><RotateCcw :size="15"/>重置视图</button><button class="button primary" @click="exportData"><Download :size="15"/>导出数据</button></div></div>
    <div class="workspace-body">
      <aside class="layer-panel" v-show="panelOpen"><div class="panel-title"><h2>{{activeTab}}</h2><button class="icon-button" title="收起面板" @click="panelOpen=false"><PanelLeftClose :size="17"/></button></div><div class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索节点名称或区域…"/><kbd>⌕</kbd></div><div class="filter-label">研究区域 <SlidersHorizontal :size="13"/></div><div class="select-wrap"><MapPinned :size="15"/><select v-model="district"><option>全部区域</option><option v-for="d in districts" :key="d">{{d}}</option></select><ChevronDown :size="14"/></div>
        <template v-if="activeTab==='空间探索'"><div class="section-label">可视化方式</div><div class="segmented"><button v-for="m in ['散点分布','热力密度']" :class="{chosen:mode===m}" @click="mode=m" :key="m">{{m}}</button></div><div class="section-label layer-label">数据图层 <span>03</span></div><div class="layer-row" v-for="l in layers" :key="l.id"><button class="check-box" :class="{checked:l.visible}" @click="l.visible=!l.visible" :aria-label="'切换'+l.name"><Check v-if="l.visible" :size="12"/></button><div class="layer-symbol" :style="{color:l.color}"><Layers3 v-if="l.id==='boundary'" :size="18"/><Navigation v-else-if="l.id==='routes'" :size="18"/><MapPinned v-else :size="18"/></div><div><strong>{{l.name}}</strong><small>{{l.sub}}</small></div></div><div class="layer-tip"><CircleHelp :size="13"/>点击地图节点查看详细属性</div><div class="section-label">底图样式</div><div class="basemap-grid"><button v-for="(b,i) in ['浅色地图','标准地图','夜间地图']" :key="b" :class="{selected:basemap===b}" @click="basemap=b"><div :class="['map-swatch','swatch-'+i]"><span/><Map :size="22"/><i v-if="basemap===b"><Check :size="10"/></i></div><small>{{b}}</small></button></div></template>
        <template v-else-if="activeTab==='数据目录'"><div class="section-label">节点目录 · {{filtered.length}}</div><div class="catalog"><button v-for="f in filtered" :key="f.properties?.id" @click="focusSite(f.properties?.id)"><MapPinned :size="16"/><div>{{f.properties?.name}}<small>{{f.properties?.district}} · {{f.properties?.status}}</small></div><ChevronRight :size="14"/></button><p v-if="!filtered.length">没有匹配的节点</p></div></template>
        <template v-else><div class="section-label">区域统计</div><div class="analysis-box"><span>平均活跃指数</span><strong>{{average}}<small>/100</small></strong><div class="progress"><i :style="{width:average+'%'}"/></div></div><div class="analysis-box"><span>需要关注的节点</span><strong>{{attention}}<small>个</small></strong><p>基于模拟状态标记统计</p></div><button class="button full" @click="mode='热力密度';activeTab='空间探索'">查看空间密度 <ArrowUpRight :size="15"/></button><p class="analysis-note">本演示采用固定种子的模拟节点。统计结果随区域与搜索筛选更新，不代表真实监测数据。</p></template>
        <div class="panel-footer"><span><i/>数据已加载</span><span>WGS 84</span></div>
      </aside>
      <main class="map-stage"><div ref="mapEl" class="map-canvas"/><button v-if="!panelOpen" class="restore-panel" @click="panelOpen=true"><Layers3 :size="18"/>图层</button>
        <div class="map-topbar"><div class="map-badge"><span class="pulse-dot"/>上海中心城区 <span class="muted">/</span> {{mode}}</div><div class="map-top-right"><span class="map-chip"><Sun :size="14"/>{{String(time).padStart(2,'0')}}:00 模拟时段</span><button class="map-icon" title="切换倾斜视角" @click="map?.easeTo({pitch:map.getPitch()>0?0:50,bearing:map.getPitch()>0?0:-20})">3D</button></div></div>
        <div class="stats-overlay"><div class="stat-card"><div class="stat-label"><span>感知节点</span><MapPinned :size="16"/></div><strong>{{filtered.length}}<small>个</small></strong><div class="stat-foot"><span class="green">{{((filtered.length/180)*100).toFixed(0)}}%</span> 当前筛选覆盖率</div><div class="sparkline"><i v-for="(h,i) in [12,18,14,25,20,29,23,34,30,39,34,42]" :key="i" :style="{height:h+'px'}"/></div></div><div class="stat-card"><div class="stat-label"><span>平均活跃指数</span><Activity :size="16"/></div><strong>{{average}}<small>/100</small></strong><div class="stat-foot"><span class="blue">模拟指标</span> 区域综合均值</div><svg class="mini-line" viewBox="0 0 130 45"><path d="M0 40 L12 31 L24 34 L36 22 L48 26 L60 16 L72 19 L84 9 L96 14 L108 5 L130 8" fill="none" stroke="#6480e8" stroke-width="2"/></svg></div><div class="stat-card"><div class="stat-label"><span>关注节点</span><Crosshair :size="16"/></div><strong>{{attention}}<small>个</small></strong><div class="stat-foot"><span class="orange">需关注</span> 模拟状态筛选</div><div class="status-meter"><i/><i/><i/><i/><i class="warm"/></div></div></div>
        <div class="map-tools"><button title="放大" @click="map?.zoomIn()"><Plus :size="19"/></button><button title="缩小" @click="map?.zoomOut()"><Minus :size="19"/></button><div/><button title="朝北" @click="map?.easeTo({bearing:0,pitch:0})"><Compass :size="19"/></button><button title="回到研究区域" @click="reset"><LocateFixed :size="19"/></button><button title="距离测量" :class="{toolActive:measuring}" @click="toggleMeasure"><Ruler :size="19"/></button><button title="全屏地图" @click="mapEl?.parentElement?.requestFullscreen().catch(()=>notify('浏览器不支持全屏'))"><Maximize :size="18"/></button></div>
        <div v-if="measuring" class="measure-banner"><Ruler :size="16"/>累计距离 {{measureLength}} km · {{measurePoints.length}} 个点<button @click="toggleMeasure"><X :size="14"/></button></div>
        <div v-if="selected" class="feature-card"><div class="feature-head"><span><i/>节点详情</span><button @click="selected=null"><X :size="16"/></button></div><h3>{{selected.name}}</h3><p>{{selected.district}} · 城市感知网络</p><div class="feature-properties"><span>节点编号</span><strong>SH-{{String(selected.id).padStart(4,'0')}}</strong><span>活跃指数</span><strong>{{selected.value}} / 100</strong><span>运行状态</span><strong :class="selected.status==='需关注'?'orange':'green'">{{selected.status}}</strong><span>数据来源</span><strong>模拟演示数据</strong></div><button class="button full" @click="focusSite(selected.id)"><LocateFixed :size="14"/>定位此节点</button></div>
        <div class="legend"><div class="legend-heading">图例 <span>{{mode==='热力密度'?'节点密度':'节点类型'}}</span></div><template v-if="mode==='散点分布'"><div v-for="(n,i) in ['城市服务','交通监测','环境感知','公共设施']" :key="n"><i :style="{background:['#5d7ce9','#22b5a1','#efa94e','#a377d9'][i]}"/>{{n}}</div></template><template v-else><div class="heat-gradient"/><div class="gradient-label"><span>低</span><span>高</span></div></template></div>
        <div v-if="mapError" class="map-warning">部分底图资源无法加载。模拟数据图层仍可使用；底图需要网络与 WebGL 支持。</div>
        <div class="timeline"><button class="play-button" @click="togglePlay" :title="timelinePlaying?'暂停':'播放模拟时段'">{{timelinePlaying?'Ⅱ':'▶'}}</button><div class="timeline-caption"><strong>时间切片</strong><span>模拟日内密度</span></div><div class="timeline-track"><input type="range" min="0" max="23" v-model.number="time" aria-label="模拟小时"/><div><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:00</span></div></div><div class="time-value">{{String(time).padStart(2,'0')}}:00 <ChevronDown :size="13"/></div></div>
        <div class="map-status"><span><MousePointer2 :size="12"/>{{coordinates}}</span><span>缩放 {{zoom.toFixed(1)}} <i/> EPSG:4326 <i/> MapLibre GL</span></div>
      </main>
    </div>
    <footer class="app-footer"><span>ATLAS GEOSPATIAL PLATFORM <b>v1.0</b></span><span>演示工作空间 <i/> 数据仅供可视化演示</span><span><span class="green">●</span> {{ready?'地图引擎就绪':'地图引擎初始化中'}}</span></footer>
  </div>
  <div v-if="toast" class="toast"><Check :size="17"/>{{toast}}</div><div v-if="notice" class="notice-popover"><strong>工作空间通知</strong><p>180 个模拟节点已准备完成。</p><p>底图由 OpenStreetMap 提供，需联网加载。</p><button class="button" @click="notice=false">知道了</button></div>
</div>
</template>
